$(document).ready(function(){$("#internal-test-submit").click(function(n){n.preventDefault();$("#errorMsg").hide();const r=$("#account-test").val().replaceAll(/\s/g,""),t=r.split(";").filter(n=>n),i=$("#OriginalAccountTest").val().split(";").filter(n=>n),u=i.filter(n=>!t.some(t=>t.toLowerCase()===n.toLowerCase())),f=t.filter(n=>!i.some(t=>t.toLowerCase()===n.toLowerCase()));$.ajax({type:"POST",url:"/internalTestAccount/update",data:{addAccounts:f,deletedAccounts:u},dataType:"json",success:function(n){if(n.success)$("#successMsg").text("Update successful!").show(),setTimeout(function(){location.reload()},1e3);else if(n.invalidAccounts&&n.invalidAccounts.length>0){let t=n.invalidAccounts.join(", ");$("#errorMsg").html(`<strong>Invalid Accounts:</strong> ${t}`).show()}else $("#errorMsg").text("Update failed due to an unknown error.").show()},error:function(){$("#errorMsg").text("An error occurred. Please try again.").show()}})})});